def apply_rules(grid):
    rows, cols = len(grid), len(grid[0])
    new_grid = [row[:] for row in grid]

    # Apply Rule 1 (Growth: 3 infected -> 4 infected)
    for r in range(rows - 1):
        for c in range(cols - 1):
            block = [
                [grid[r][c], grid[r][c+1]],
                [grid[r+1][c], grid[r+1][c+1]]
            ]
            infected_count = sum(sum(cell for cell in block))

            if infected_count == 3:
                # Find the sterile section and infect it
                if block[0][0] == 0: new_grid[r][c] = 1
                elif block[0][1] == 0: new_grid[r][c+1] = 1
                elif block[1][0] == 0: new_grid[r+1][c] = 1
                elif block[1][1] == 0: new_grid[r+1][c+1] = 1

    # Apply Rule 2 (Mutation: 2 infected -> flip)
    for r in range(rows - 1):
        for c in range(cols - 1):
            block = [
                [grid[r][c], grid[r][c+1]],
                [grid[r+1][c], grid[r+1][c+1]]
            ]
            infected_count = sum(sum(cell for cell in block))

            if infected_count == 2:
                # Flip the colors in the block
                for dr, dc in [(0, 0), (0, 1), (1, 0), (1, 1)]:
                    if new_grid[r+dr][c+dc] == 1:
                        new_grid[r+dr][c+dc] = 0
                    else:
                        new_grid[r+dr][c+dc] = 1
    return new_grid

