def simulate_spread(grid, max_steps=500):
    N = len(grid)
    current_grid = [row[:] for row in grid]

    for step in range(max_steps):
        new_grid = [row[:] for row in current_grid]
        change_occurred = False

        # Iterate over all possible 2x2 top-left corners (i, j)
        for i in range(N - 1):
            for j in range(N - 1):

                # Extract the 2x2 block and calculate infected count
                cells = [
                    current_grid[i][j], current_grid[i][j+1],
                    current_grid[i+1][j], current_grid[i+1][j+1]
                ]
                count = sum(cells)

                # Rule 1: Exactly three infected sections -> last sterile section gets infected
                if count == 3:
                    # Find the sterile section (0)
                    sterile_cells = []
                    if cells[0] == 0: sterile_cells.append((i, j))
                    if cells[1] == 0: sterile_cells.append((i, j+1))
                    if cells[2] == 0: sterile_cells.append((i+1, j))
                    if cells[3] == 0: sterile_cells.append((i+1, j+1))

                    # There is exactly one sterile cell in a count=3 scenario
                    if sterile_cells:
                        r, c = sterile_cells[0]
                        # Infect it (set to 1)
                        if new_grid[r][c] == 0:
                            new_grid[r][c] = 1
                            change_occurred = True

                # Rule 2: Exactly two infected sections -> mutation (flip)
                elif count == 2:
                    # Flip all four cells in the new grid
                    for r_offset, c_offset in [(0, 0), (0, 1), (1, 0), (1, 1)]:
                        r, c = i + r_offset, j + c_offset

                        # Flip: 1 -> 0, 0 -> 1
                        if new_grid[r][c] == 1:
                            new_grid[r][c] = 0
                        else:
                            new_grid[r][c] = 1
                    change_occurred = True

        # Update grid for the next step
        current_grid = new_grid

        # Check for full infection
        total_infected = sum(sum(row) for row in current_grid)
        if total_infected == N * N:
            print(f"FULL INFECTION ACHIEVED at step {step + 1}")
            return current_grid

        if not change_occurred and step > 0:
            print(f"STASIS REACHED at step {step + 1} with {total_infected} infected cells.")
            return current_grid

    print(f"MAX STEPS REACHED ({max_steps}) with {sum(sum(row) for row in current_grid)} infected cells.")
    return current_grid

